"""Explicit LanceDB schema; embeddings are supplied locally, never auto-generated."""

import json
from dataclasses import replace
from pathlib import Path

import lancedb
import pyarrow as pa

from uni_rag.models import Chunk


class VectorStore:
    def __init__(self, directory: Path):
        directory.mkdir(parents=True, exist_ok=True)
        self.db = lancedb.connect(str(directory))
        self.table = (
            self.db.open_table("chunks") if "chunks" in self.db.list_tables().tables else None
        )

    def upsert(self, chunks: list[Chunk], vectors: list[list[float]]) -> None:
        if len(chunks) != len(vectors):
            raise ValueError("Chunk and vector counts differ")
        if not chunks:
            return
        rows = [
            {"id": c.id, "text": c.text, "metadata": json.dumps(c.metadata()), "vector": v}
            for c, v in zip(chunks, vectors, strict=True)
        ]
        if self.table is None:
            schema = pa.schema(
                [
                    ("id", pa.string()),
                    ("text", pa.string()),
                    ("metadata", pa.string()),
                    ("vector", pa.list_(pa.float32(), len(vectors[0]))),
                ]
            )
            self.table = self.db.create_table("chunks", data=rows, schema=schema)
        else:
            self.table.merge_insert(
                "id"
            ).when_matched_update_all().when_not_matched_insert_all().execute(rows)

    def chunks(self) -> list[Chunk]:
        if self.table is None:
            return []
        return [
            Chunk.from_row(row)
            for row in self.table.search().select(["id", "text", "metadata"]).limit(None).to_list()
        ]

    def ids(self) -> set[str]:
        if self.table is None:
            return set()
        return {row["id"] for row in self.table.search().select(["id"]).limit(None).to_list()}

    def search(self, vector: list[float], k: int, eligible: set[str] | None = None) -> list[Chunk]:
        if self.table is None:
            return []
        if eligible is not None and not eligible:
            return []
        query = self.table.search(vector).metric("cosine")
        if eligible is not None:
            # IDs are SHA1 hex strings generated by chunker, never user SQL.
            if any(
                len(identifier) != 40 or not all(c in "0123456789abcdef" for c in identifier)
                for identifier in eligible
            ):
                raise ValueError("Invalid chunk identifier")
            query = query.where(
                "id IN (" + ",".join(f"'{i}'" for i in eligible) + ")", prefilter=True
            )
        rows = query.limit(k).to_list()
        return [Chunk.from_row(row) for row in rows]

    def delete(self, ids: set[str]) -> None:
        if self.table is not None:
            for identifier in ids:
                self.table.delete(f"id = '{identifier}'")

    def reconcile(self, files: list[dict]) -> list[Chunk]:
        """Derive all duplicate locations from the authoritative completed-file manifest."""
        by_hash: dict[str, list[dict]] = {}
        for item in files:
            by_hash.setdefault(item["sha1"], []).append(item)
        active = []
        for chunk in self.chunks():
            aliases = by_hash.get(chunk.content_hash, [])
            if not aliases:
                continue
            template = chunk.locations[0]
            locations = [
                replace(
                    template,
                    source=f["source"],
                    path=f["path"],
                    file_type=Path(f["path"]).suffix.lower(),
                    mtime_ns=f["mtime_ns"],
                )
                for f in aliases
            ]
            if chunk.locations != locations:
                chunk.locations = locations
                self.table.update(
                    where=f"id = '{chunk.id}'", values={"metadata": json.dumps(chunk.metadata())}
                )
            active.append(chunk)
        return active

    def clear(self) -> None:
        if self.table is not None:
            self.db.drop_table("chunks")
            self.table = None
